module bamboo_max_d (\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] n,\n    input [7:0] a [0:7],\n    input [15:0] k,\n    output reg [7:0] max_d,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE       = 3'd0;\n    localparam [2:0] ITERATE_D  = 3'd1;\n    localparam [2:0] COMPUTE_SUM = 3'd2;\n    localparam [2:0] CHECK      = 3'd3;\n    localparam [2:0] UPDATE     = 3'd4;\n    localparam [2:0] COMPLETE   = 3'd5;\n\n    reg [2:0] state;\n    reg [8:0] d;                  // Current d (1-256)\n    reg [15:0] sum;               // Current sum\n    reg [2:0] bamboo_idx;        // Bamboo index\n    reg [8:0] max_d_reg;         // Internal max_d register\n    wire [2:0] n_minus_1 = n - 3'd1;\n\n    // Calculation wires\n    wire [7:0] current_a;\n    wire [8:0] d_minus_1;\n    wire [8:0] add_numerator;\n    wire [7:0] ceil_val;\n    wire [15:0] ceil_times_d;\n    wire [15:0] term;\n\n    assign current_a = a[bamboo_idx];\n    assign d_minus_1 = d - 9'd1;\n    assign add_numerator = {1'b0, current_a} + d_minus_1; // 9 bits\n    assign ceil_val = add_numerator / d;\n    assign ceil_times_d = ceil_val * d;\n    assign term = ceil_times_d - {8'd0, current_a};\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            max_d_reg <= 9'd0;\n            done <= 1'b0;\n            d <= 9'd1;\n            sum <= 16'd0;\n            bamboo_idx <= 3'd0;\n            max_d <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        d <= 9'd1;\n                        max_d_reg <= 9'd0;\n                        state <= ITERATE_D;\n                    end\n                end\n\n                ITERATE_D: begin\n                    sum <= 16'd0;\n                    bamboo_idx <= 3'd0;\n                    state <= COMPUTE_SUM;\n                end\n\n                COMPUTE_SUM: begin\n                    sum <= sum + term;\n                    bamboo_idx <= bamboo_idx + 3'd1;\n                    if (bamboo_idx == n_minus_1) begin\n                        state <= CHECK;\n                    end else begin\n                        state <= COMPUTE_SUM;\n                    end\n                end\n\n                CHECK: begin\n                    if (sum <= k) begin\n                        max_d_reg <= d;\n                    end\n                    state <= UPDATE;\n                end\n\n                UPDATE: begin\n                    d <= d + 9'd1;\n                    if (d < 9'd256) begin\n                        state <= ITERATE_D;\n                    end else begin\n                        state <= COMPLETE;\n                    end\n                end\n\n                COMPLETE: begin\n                    done <= 1'b1;\n                    max_d <= max_d_reg[7:0];\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule